// === Tab: mySketch ===
// config
let NODES_ROWS = 10
let NODES_COLS = 10
let FISH_NUM = 20
const MESH_STROKE = false

// nodes
let nodes = []
let mesh_width_space
let mesh_height_space

// attractor
let attractor
let fish
let fishes = []

let clicking = false

function setup() {
	createCanvas(windowWidth, windowHeight);
	colorMode(HSB, 100);

	if(isSmartPhone()){
		 NODES_ROWS = 10
		 NODES_COLS = 5
		 FISH_NUM = 5
	}

	mesh_width_space = 0 //width/8
	mesh_height_space = 0 //height/8

	for(let i=0; i < NODES_ROWS; i++){
		for(let j=0; j < NODES_COLS; j++){
			nodes.push(new Node(
				((width - mesh_width_space/2)/(NODES_COLS-1)*j+mesh_width_space/2),
				((height - mesh_height_space/2)/(NODES_ROWS-1)*i + mesh_height_space/2),
				j + i*NODES_COLS
			))
		}
	}

	// Attractor
	attractor = new Attractor((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 200)

	// Fish
	fish = new Fish(width/2, height/2, 50)
	for(let i=0; i<FISH_NUM; i++){
		fishes.push(new Fish(random(0,width), random(0,height), random(40,80)))
	}
}


function draw() {
	// Init
	background(55, 50, 90)

	// status update
	checkInteraction()

	// Nodes
	nodes.forEach(e => {
		const targets = e.getInteractionTargets(nodes)
		targets.forEach(target => e.interactWith(target))
		e.update()
		e.draw()
		if(clicking){
			attractor.attract(e)
		}
		fishes.forEach(fish=>{
			fish.attract(e)
		})
	})

	// Attractor
	attractor.update()
	attractor.draw()


	// Fish
	fishes.forEach(fish => {
		fish.update()
		fish.draw()
	})
	drawMesh(nodes, NODES_COLS, NODES_ROWS)
}

////////////////

/*
	Helper Functions
*/

function isSmartPhone() {
  if (window.matchMedia && window.matchMedia('(max-device-width: 640px)').matches) {
    return true;
  } else {
    return false;
  }
}

function checkInteraction(){
	if(((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))){
		clicking = true
	}else{
		clicking = false
	}
}


function drawMesh(nodes, cols_num, rows_num){
	push()
	blendMode(ADD);
	for(let y=0; y<rows_num-1; y++){
		for(let x=0; x<cols_num-1; x++){
			beginShape(TRIANGLE_STRIP)
			const first = nodes[x+y*cols_num] // 0+0 = 0
			const second = nodes[x+(y+1)*cols_num] // 0+10 = 10
			const third = nodes[(x+1)+y*cols_num] // 1+0 = 1
			const forth = nodes[(x+1)+(y+1)*cols_num] // 1+10 = 11

			const d_1_2 = map((first.d + second.d) / 2, 0, width/cols_num, 0, 100)
			const d_2_3 = map((second.d + third.d) / 2, 0, width/cols_num, 0, 100)
			const d_3_4 = map((third.d + forth.d) / 2, 0, width/cols_num, 0, 100)
			const d_1_2_3 = map((d_1_2 * 2 + third.d) / 3, 0, width/cols_num, 0, 100)
			const d_2_3_4 = map((d_2_3 * 2 + forth.d) / 3, 0, width/cols_num, 0, 100)

			stroke(20, d_1_2/6, 100, d_1_2) // for first stroke
			if(!MESH_STROKE){noStroke()}
			fill(20, d_1_2_3/4, 100, d_1_2_3/2) // for first fill
			vertex(first.x, first.y)
			vertex(second.x, second.y)
			stroke(20, d_3_4/6, 100, d_3_4) // for second stroke
			if(!MESH_STROKE){noStroke()}
			vertex(third.x, third.y)
			stroke(20, d_3_4/6, 100, d_3_4) // for third stroke
			if(!MESH_STROKE){noStroke()}
			fill(20, d_2_3_4/4, 100, d_2_3_4/2) // for second surface
			vertex(forth.x, forth.y)
			endShape()
		}
	}
	pop()
}


/*
	Classes
*/

class Node{
	constructor(init_x, init_y, id, r=10){
		this.x = init_x
		this.y = init_y
		this.init_x = init_x
		this.init_y = init_y
		this.id = id
		this.r = r
		this.dx = 0
		this.dy = 0
		this.d = 0
	}

	update(){
		this.dx = (this.init_x - this.x)
		this.dy = (this.init_y - this.y)
		this.d = mag(this.dx, this.dy)
		this.x += this.dx / this.r / this.r
		this.y += this.dy / this.r / this.r
	}

	draw(){
		const normalizedD = map(this.d, 0, this.r*2, 0, 1)
		noStroke()
		fill(60, normalizedD*100, normalizedD*100)
		//circle(this.x, this.y, this.r + (this.r / 2 * normalizedD) )
		//text(str(this.id), this.x, this.y) // debug

	}

	interactWith(node){
		const offsetX = node.init_x - this.init_x
		const offsetY = node.init_y - this.init_y
		const offsetD = mag(offsetX, offsetY)
		const dx = node.x - this.x
		const dy = node.y - this.y
		const d = mag(dx, dy)

		if( offsetD > d){
			const magnitude = mag(d, offsetD)
			const s = magnitude / this.r
			const f = (1 / pow(s, 0.5) - 1) / this.r

			node.x += (dx - offsetX) * f
			node.y += (dy - offsetY) * f
		}
	}

	getInteractionTargets(nodes){
		let result = []

		const targetIndexDiff = [-NODES_COLS-1, -NODES_COLS, -NODES_COLS+1, -1, +1, NODES_COLS-1,  NODES_COLS, NODES_COLS+1]
		const targetCandidateIndex = targetIndexDiff.map(e => e + this.id)
		const targetIndex = targetCandidateIndex.filter(e => 0 <= e && e <= NODES_COLS * NODES_ROWS - 1 )
		var targets = targetIndex.map(e => nodes[e])

		return targets
	}
}


class Attractor{
	constructor(init_x, init_y, r=50){
		this.x = init_x
		this.y = init_y
		this.init_x = init_x
		this.init_y = init_y
		this.r = r
	}

	attract(node){
		var dx = node.x - this.x
		var dy = node.y - this.y
		var d = mag(dx, dy)

		if( 0 <= d && d <= this.r){
			var s = d / this.r
			var f = 1 / pow(s, 0.5) - 1

			node.x += dx * f
			node.y += dy * f
		}
	}

	update(){
		this.x = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))
		this.y = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))
	}

	draw(){
		if(clicking){
			noStroke()
			fill(200, 200, 200, 50)
		}else{
			stroke('#555')
			noFill()
		}
		//circle(this.x, this.y, this.r * 2) // for debug
	}
}


class Fish{
	constructor(init_x, init_y, r=50){
		this.x = init_x
		this.y = init_y
		this.r = r
		this.xoff = random(0, 60*60)
		this.yoff = random(0, 60*60)
		this.bodyColor = color(random(0, 100), random(30, 80), random(40,70))
		this.xHistory = []
		this.yHistory = []
		this.xVelocity = random(1, 5) * 0.001
		this.yVelocity = random(1, 5) * 0.001
	}

	attract(node){
		var dx = node.x - this.x
		var dy = node.y - this.y
		var d = mag(dx, dy)

		if( 0 <= d && d <= this.r){
			var s = d / this.r
			var f = 1 / pow(s, 0.5) - 1

			node.x += dx * f
			node.y += dy * f
		}
	}

	update(){
		this.xoff += this.xVelocity
		this.yoff += this.yVelocity
		this.x = noise(this.xoff) * width
		this.y = noise(this.yoff) * height
		if(this.xHistory.length > 3){
			this.xHistory.pop()
		}
		if(this.yHistory.length > 3){
			this.yHistory.pop()
		}
		this.xHistory.push(this.x)
		this.yHistory.push(this.y)
	}

	draw(){
		const vx = this.x - this.xHistory.reduce((acc, cur)=>acc+cur, 0)/this.xHistory.length
		const vy = this.y - this.yHistory.reduce((acc, cur)=>acc+cur, 0)/this.yHistory.length
		const baseSize = this.r * map(mag(vx, vy), 0, 100, 0.3, 0.5)

		push()
		drawingContext.shadowBlur = baseSize / 10
		drawingContext.shadowColor = this.bodyColor;
		fill(this.bodyColor)
		noStroke()
		translate(this.x, this.y)
		rotate(atan2(vy,vx))
		ellipse(0, 0, baseSize*1, baseSize*1/3)
		triangle(-baseSize/3, 0, - baseSize*2/3, -baseSize/6, -baseSize*2/3, baseSize/6)
		pop()
	}
}

